Here is the implementation of `sliding_max` using a monotonic deque for $O(n)$ time complexity:

```python
from collections import deque


def sliding_max(xs: list, w: int) -> list:
    if w < 1:
        raise ValueError("Window size w must be at least 1.")
    if w > len(xs):
        return []

    dq = deque()  # stores indices of elements in the current window, monotonically decreasing by value
    result = []

    for i, x in enumerate(xs):
        # Remove indices that are out of the current window
        while dq and dq[0] <= i - w:
            dq.popleft()

        # Remove elements smaller than the current element from the back
        while dq and xs[dq[-1]] <= x:
            dq.pop()

        dq.append(i)

        # The first window finishes at index w - 1
        if i >= w - 1:
            result.append(xs[dq[0]])

    return result
